//! Golden test: `EndIslandFunction` point and volume samples against the vanilla server
//! (fixture generated by `tests/oracle/EndIslandOracle.java`).

use std::path::PathBuf;
use std::sync::Arc;

use mc_core::ident::Identifier;
use mc_core::random::{LegacyRandomSource, RandomSource};
use mc_worldgen::densityfunction::generator::EndIslandFunction;
use mc_worldgen::densityfunction::{
    CompileContext, DensityBuffer, DensityVolume, DfOp, NoiseHolder, SamplerContext,
};
use mc_worldgen::synth::Noise;

/// `RandomState`'s compile context as far as the end island function sees it.
struct EndIslandContext {
    seed: i64,
}

impl CompileContext for EndIslandContext {
    fn create_noise_sampler(&self, _: &NoiseHolder) -> Arc<dyn Noise> {
        unreachable!("end islands use no registered noise")
    }
    fn create_random(&self, _: &Identifier) -> Box<dyn RandomSource> {
        unreachable!("end islands use no hashed random")
    }
    fn create_end_island_random(&self) -> Box<dyn RandomSource> {
        Box::new(LegacyRandomSource::new(self.seed))
    }
}

fn bits(hex: &str) -> u32 {
    u32::from_str_radix(hex, 16).expect("hex float bits")
}

#[test]
fn matches_vanilla_bit_for_bit() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/end_island.txt");
    let fixture = std::fs::read_to_string(path).expect("end_island.txt fixture");
    let ctx = SamplerContext::empty_uncached();
    let (mut points, mut volumes) = (0, 0);
    for line in fixture.lines() {
        let fields: Vec<&str> = line.split(' ').collect();
        let seed: i64 = fields[1].parse().expect("seed");
        let sampler = EndIslandFunction.compile_sampler(&EndIslandContext { seed });
        match fields[0] {
            "P" => {
                let (x, z): (i32, i32) =
                    (fields[2].parse().expect("x"), fields[3].parse().expect("z"));
                let actual = sampler.sample_value(&ctx, x, 5, z);
                assert_eq!(
                    actual.to_bits(),
                    bits(fields[4]),
                    "seed {seed} at ({x}, {z}): {actual}"
                );
                points += 1;
            }
            "V" => {
                let volume = DensityVolume::new(3, 2, 3, -1030, 0, 1018, 8, 4, 8);
                let mut out = DensityBuffer::create_unpooled(volume.size());
                sampler.sample_volume(&ctx, &mut out, &volume);
                let expected: Vec<u32> = fields[2..].iter().map(|hex| bits(hex)).collect();
                let actual: Vec<u32> = out.as_slice().iter().map(|v| v.to_bits()).collect();
                assert_eq!(actual, expected, "seed {seed} volume");
                volumes += 1;
            }
            other => panic!("unknown fixture line kind {other}"),
        }
    }
    assert_eq!((points, volumes), (768, 3));
}
